import json

R, C = 10, 8

def white(r, c):
    return (r + c) % 2 == 0   # chosen convention: white when (r+c) is even

def count(pc, qc=None):
    ways = {pc: 1}
    for r in range(1, R):
        nw = {}
        for c, w in ways.items():
            for dc in (-1, 0, 1):
                nc = c + dc
                if 0 <= nc < C and white(r, nc):
                    nw[nc] = nw.get(nc, 0) + w
        ways = nw
    return ways.get(qc, 0) if qc is not None else sum(ways.values())

options = {"A": 240, "B": 245, "C": 250, "D": 255, "E": 260}
same_col = {}
any_top = {}
for pc in range(C):
    same_col[pc] = count(pc, pc)
    any_top[pc] = count(pc)

# Look for a unique option value among the interpretations
cands = set()
for d in (same_col, any_top):
    for v in d.values():
        for k, ov in options.items():
            if v == ov:
                cands.add(k)

if len(cands) == 1:
    k = cands.pop()
    print(json.dumps({"final_answer": f"{k}: {options[k]}",
                      "evidence": {"same_col": same_col, "any_top": any_top}}))
else:
    print("UNSUPPORTED")
